class PaymentService {
  constructor(private gateway: PaymentGateway) {}
  charge(card, amount) { return this.gateway.charge(card, amount); }
  refund(txId) { return this.gateway.refund(txId); }
}

class UserRepository {
  constructor(private dao: UserDao) {}
  getUser(id: number) { return this.dao.findById(id); }
  updateUser(user) { return this.dao.save(user); }
}

